{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Practical sessions, steady progress</title>
  <meta name="description" content="A calm, private practice approach to navigating life transitions. Short-term series, ongoing circles, and guided micro-practices to restore steadiness.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="/about.html">About</a>
        <a href="/specialties.html">Focus Areas</a>
        <a href="/approach.html">How I Work</a>
        <a href="/fees.html">Investment</a>
        <a href="/faq.html">Questions</a>
        <a href="/book.html" class="cta">Schedule</a>
        <a href="/contact.html">Connect</a>
      </nav>
      <button class="mobile-toggle" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" id="hero">
      <svg class="hero-pattern" width="0" height="0" aria-hidden="true"></svg>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">Care that helps you move forward in small, steady steps</h1>
          <p class="lead">I offer short series and membership-style supports that prioritize reliability over quick fixes. Practical tools, reflective sessions, and measurable rhythms for everyday life.</p>
          <div class="hero-actions">
            <a id="primary-cta" class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="muted" href="/book.html">Schedule a 20-minute consult</a>
          </div>
          <p class="contact">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <div class="hero-panel">
          <div class="panel-box">
            <h3>Quick check-in</h3>
            <p class="muted">Not sure where to start? Select how you feel and get a recommended small plan below.</p>
            <div class="mood-selector" id="mood-main">
              <button data-key="overwhelmed">Overwhelmed</button>
              <button data-key="stuck">Stuck</button>
              <button data-key="anxious">Anxious</button>
              <button data-key="flat">Flat</button>
            </div>
            <div class="mood-output" id="mood-output">
              <h4 class="approach-title">Recommended approach</h4>
              <p class="approach-desc">Choose a mood to see a gentle next step.</p>
              <a id="mood-cta" class="small-cta" href="/book.html">Start a single session</a>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- Diagnostic -->
    <section class="diagnostic wrap">
      <h2>Short diagnostics: match method to need</h2>
      <p class="muted">There are different formats that suit different moments. Below you can explore three options and toggle how you prefer to pay.</p>
      <div class="grid diag-grid">
        <div class="card">
          <h3>Guided Series</h3>
          <p class="muted">Four sessions with targeted skills and reflections. Good for a specific focus.</p>
        </div>
        <div class="card">
          <h3>Focus Pack</h3>
          <p class="muted">A bundle of sessions for a short arc — focused work without a long commitment.</p>
        </div>
        <div class="card">
          <h3>Support Circle</h3>
          <p class="muted">A monthly membership-style option for steady check-ins and micro-practices.</p>
        </div>
      </div>

      <div class="pricing-comparator" id="pricing-comparator">
        <div class="toggle">
          <label class="switch" aria-hidden="true">
            <input type="checkbox" id="price-toggle">
            <span class="slider"></span>
          </label>
          <div class="labels"><span>Monthly</span><span>Package</span></div>
        </div>
        <div class="prices">
          <div class="price-card">
            <div class="name">Guided Series</div>
            <div class="price" data-month="150" data-package="540">$150</div>
            <div class="meta">per session / 4-session series</div>
          </div>
          <div class="price-card">
            <div class="name">Focus Pack</div>
            <div class="price" data-month="95" data-package="320">$95</div>
            <div class="meta">per session / 4-session bundle</div>
          </div>
          <div class="price-card">
            <div class="name">Support Circle</div>
            <div class="price" data-month="55" data-package="500">$55</div>
            <div class="meta">monthly access / includes resources</div>
          </div>
        </div>
      </div>
    </section>

    <!-- Plan / Micro-habits -->
    <section class="plan wrap">
      <h2>Practical plans and small habits</h2>
      <p class="muted">Plans break down into tiny practices you can try between sessions. Practice is about regular, manageable moves, not intensity.</p>

      <div class="micro-grid">
        <div class="micro">
          <h4>Two-minute ground</h4>
          <p class="muted">A short breathing routine to return to your body in moments of overwhelm.</p>
        </div>
        <div class="micro">
          <h4>Priority note</h4>
          <p class="muted">A single-sentence check-in you write each morning to orient attention.</p>
        </div>
        <div class="micro">
          <h4>Mini-reflect</h4>
          <p class="muted">Three questions to answer once a week to notice small shifts.</p>
        </div>
      </div>

      <div class="mini-mood" id="mood-mini">
        <h3>Try the mini selector</h3>
        <p class="muted">Pick a mood and get a micro-practice suggestion that fits that moment.</p>
        <div class="mood-selector small">
          <button data-key="overwhelmed">Overwhelmed</button>
          <button data-key="stuck">Stuck</button>
          <button data-key="anxious">Anxious</button>
          <button data-key="flat">Flat</button>
        </div>
        <div class="mood-output small" id="mood-output-mini">
          <p class="approach-desc">Select a mood to receive a practice.</p>
          <a id="mood-cta-mini" class="small-cta" href="/book.html">Book a check-in</a>
        </div>
      </div>

    </section>

    <!-- CTA -->
    <section class="cta wrap">
      <div class="cta-inner">
        <div>
          <h2>Ready for a steady plan?</h2>
          <p class="muted">I offer a short introductory conversation so we can decide together what format fits your current needs.</p>
        </div>
        <div>
          <a id="final-cta" class="primary" href="/book.html">Schedule an introductory call</a>
          <p class="muted small">Confidentiality and boundaries: sessions are confidential within legal and ethical limits. I will clarify scope and referral needs. If you are in crisis or danger, call your local emergency services or the appropriate crisis line.</p>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="footer-left">
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Private practice therapist • {{CITY}}, {{STATE}}</p>
      </div>
      <div class="footer-right">
        <p class="muted">Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p class="muted">I maintain confidentiality and will discuss limits and referrals when appropriate. This site is informational and not a substitute for direct clinical care.</p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
