{"path":"assets/css/styles.css","content":"/* Base styles */
:root{
  --bg:#fbfbfc;--muted:#6b7280;--accent:#2b6cb0;--card:#ffffff;--shadow:rgba(16,24,40,0.06);
  --radius:12px;--max:1100px;--gap:20px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.45;color:#0f172a;background:var(--bg);margin:0}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,#fff,transparent);border-bottom:1px solid #eef2f7}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:600;color:var(--accent);text-decoration:none}
.nav a{margin-left:14px;color:#111827;text-decoration:none}
.nav a.cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.mobile-toggle{display:none}

.hero{background:linear-gradient(180deg,rgba(43,108,176,0.06),transparent);padding:48px 0;position:relative;overflow:hidden}
.hero-pattern{position:absolute;right:0;top:0;opacity:0.14}
.hero-inner{display:flex;gap:28px;align-items:stretch}
.hero-copy{flex:1}
.title{font-size:clamp(20px,3.4vw,32px);margin:0 0 10px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-actions a{margin-right:12px;text-decoration:none}
.primary{background:var(--accent);color:#fff;padding:10px 16px;border-radius:10px}
.muted{color:var(--muted)}
.hero-panel{width:320px}
.panel-box{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 6px 18px var(--shadow)}
.mood-selector{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.mood-selector button{background:#f7fafc;border:1px solid #e6eef9;padding:8px 10px;border-radius:8px;cursor:pointer}
.mood-output{margin-top:12px}
.small-cta{display:inline-block;margin-top:10px;background:#eef6ff;color:var(--accent);padding:8px 12px;border-radius:8px;text-decoration:none}

.wrap h2{margin-top:6px}
.diagnostic{padding:38px 0}
.diag-grid{display:flex;gap:16px}
.card{background:var(--card);padding:16px;border-radius:10px;box-shadow:0 6px 18px var(--shadow);flex:1}
.pricing-comparator{margin-top:18px;background:linear-gradient(180deg,#fff, #fbfdff);padding:14px;border-radius:12px;box-shadow:0 6px 18px var(--shadow)}
.toggle{display:flex;align-items:center;gap:12px}
.switch{position:relative;display:inline-block;width:44px;height:24px}
.switch input{display:none}
.slider{position:absolute;top:0;left:0;right:0;bottom:0;background:#e6eef9;border-radius:999px}
.slider:before{content:"";position:absolute;height:18px;width:18px;border-radius:50%;background:#fff;top:3px;left:3px;transition:transform .22s}
.switch input:checked + .slider:before{transform:translateX(20px)}
.labels{display:flex;justify-content:space-between;color:var(--muted);font-size:13px}
.prices{display:flex;gap:12px;margin-top:12px}
.price-card{flex:1;background:var(--card);padding:12px;border-radius:8px;text-align:center}
.price{font-weight:700;font-size:20px;margin:6px 0}
.meta{color:var(--muted);font-size:13px}

.plan{padding:34px 0}
.micro-grid{display:flex;gap:12px}
.micro{flex:1;background:var(--card);padding:16px;border-radius:10px}
.mini-mood{margin-top:18px;padding:12px;background:linear-gradient(180deg,#fff,#fcfeff);border-radius:10px}
.mood-selector.small button{padding:6px 8px}

.cta{background:linear-gradient(180deg,#f7fbff,transparent);padding:28px 0}
.cta-inner{display:flex;justify-content:space-between;align-items:center}
.small{font-size:13px}

.site-footer{border-top:1px solid #eef2f7;padding:22px 0;background:#fff}
.footer-left{float:left}
.footer-right{float:right;text-align:right}

/* Responsive */
@media (max-width:880px){
  .hero-inner,.diag-grid,.prices,.micro-grid,.cta-inner{flex-direction:column}
  .nav{display:none}
  .mobile-toggle{display:inline-block}
  .footer-right,.footer-left{float:none;text-align:left}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Pricing comparator
  const toggle = document.getElementById('price-toggle');
  const priceEls = Array.from(document.querySelectorAll('.price'));
  function animatePrice(el, start, end){
    const startTime = performance.now();
    const duration = 420;
    const from = +start;
    const to = +end;
    function tick(now){
      const t = Math.min(1,(now - startTime)/duration);
      const val = Math.round(from + (to - from) * (0.5 - 0.5*Math.cos(Math.PI * t))); // ease
      el.textContent = '$' + val;
      if(t < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }
  // initialize
  priceEls.forEach(el => {
    const m = el.getAttribute('data-month');
    el.textContent = '$' + m;
    el._current = +m;
  });
  toggle.addEventListener('change', () => {
    const toPackage = toggle.checked;
    priceEls.forEach(el => {
      const month = +el.getAttribute('data-month');
      const pack = +el.getAttribute('data-package');
      const target = toPackage ? pack : month;
      animatePrice(el, el._current, target);
      el._current = target;
    });
  });

  // Mood-to-Method selector logic
  const MOODS = {
    overwhelmed: {
      title: 'Short stabilization plan',
      desc: 'Begin with grounding practices and one focused session to reduce immediate pressure. A clear, limited agenda helps restore decision space.',
      cta: 'Book a stabilization session',
      href: '/book.html'
    },
    stuck: {
      title: 'Targeted orientation series',
      desc: 'A short 3–4 session arc to map patterns and try small experiments. Useful when you want directional clarity without long-term commitment.',
      cta: 'Start a focused series',
      href: '/fees.html'
    },
    anxious: {
      title: 'Skill-focused check-ins',
      desc: 'Brief sessions that teach a few practical skills to lower activation and increase choice in anxious moments.',
      cta: 'Schedule a skill session',
      href: '/book.html'
    },
    flat: {
      title: 'Routine-building circle',
      desc: 'Gentle, regular touchpoints and micro-habits to help reconnect with values and everyday pleasure.',
      cta: 'Join the support circle',
      href: '/fees.html'
    }
  };

  function setupMoodSelector(rootId, outputId, ctaId){
    const root = document.getElementById(rootId);
    if(!root) return;
    const output = document.getElementById(outputId);
    const cta = document.getElementById(ctaId);
    root.addEventListener('click', (e)=>{
      const btn = e.target.closest('button');
      if(!btn) return;
      const key = btn.getAttribute('data-key');
      const data = MOODS[key];
      if(!data) return;
      // visual active
      Array.from(root.querySelectorAll('button')).forEach(b=>b.classList.toggle('active', b===btn));
      // simple morph animation for output
      output.style.opacity = 0.15;
      setTimeout(()=>{
        output.querySelector('.approach-title')?.remove();
        const title = document.createElement('h4');
        title.className = 'approach-title';
        title.textContent = data.title;
        const desc = output.querySelector('.approach-desc') || document.createElement('p');
        desc.className = 'approach-desc';
        desc.textContent = data.desc;
        output.insertBefore(title, output.firstChild);
        if(!output.contains(desc)) output.appendChild(desc);
        cta.textContent = data.cta;
        cta.href = data.href;
        output.style.opacity = 1;
      },200);
    });
  }
  setupMoodSelector('mood-main','mood-output','mood-cta');
  setupMoodSelector('mood-mini','mood-output-mini','mood-cta-mini');

  // Mobile menu
  const mobileToggle = document.querySelector('.mobile-toggle');
  mobileToggle && mobileToggle.addEventListener('click', ()=>{
    const nav = document.querySelector('.nav');
    nav.style.display = nav.style.display === 'flex' ? 'none' : 'flex';
    nav.style.flexDirection = 'column';
  });

})();"} 
